/** All strategic priorities for an industry (empty if not covered yet). */
export function getStrategicPrioritiesForIndustry(
	industryCode: string,
): StrategicPriorityIndexEntry[] {
	return STRATEGIC_PRIORITY_INDEX.filter((p) => p.industryCode === industryCode);
}

/** Client-side mirror of the server auto-match, for the sub-selector default. */
export function matchStrategicPriorityId(
	industryCode: string,
	jobTitle: string | undefined | null,
): string | null {
	const all = getStrategicPrioritiesForIndustry(industryCode);
	if (all.length === 0) return null;
	const title = (jobTitle ?? "").trim().toLowerCase();
	if (title) {
		const match = all.find((p) =>
			p.targetPersonas.some(
				(persona) =>
					title.includes(persona.toLowerCase()) || persona.toLowerCase().includes(title),
			),
		);
		if (match) return match.id;
	}
	return all[0]!.id;
}
